import * as THREE from './three.module.js';
export class SurfaceScene {
 constructor(el){this.el=el;this.scene=new THREE.Scene();this.scene.background=new THREE.Color('#e8eeea');this.camera=new THREE.PerspectiveCamera(45,1,.01,100);this.renderer=new THREE.WebGLRenderer({antialias:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));el.append(this.renderer.domElement);this.target=new THREE.Vector3(0,0,.8);this.radius=4;this.yaw=.4;this.pitch=.15;
  const grid=new THREE.GridHelper(6,30,0x98aaa0,0xc5d2ca);grid.position.y=-1.2;this.scene.add(grid);this.scene.add(new THREE.AxesHelper(.5));this.objects=new THREE.Group();this.scene.add(this.objects);this.camGroup=new THREE.Group();this.scene.add(this.camGroup);
  // The reference axes/grid are guides; an unmeasured wall is never rendered.
  this.geometry=new THREE.BufferGeometry();this.cloud=new THREE.Points(this.geometry,new THREE.PointsMaterial({size:.016,vertexColors:true,sizeAttenuation:true}));this.objects.add(this.cloud);
  this.surface=new THREE.Mesh(new THREE.BufferGeometry(),new THREE.MeshBasicMaterial({vertexColors:true,side:THREE.DoubleSide,polygonOffset:true,polygonOffsetFactor:1,polygonOffsetUnits:1}));this.objects.add(this.surface);
  let drag=null;const c=this.renderer.domElement;c.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];c.setPointerCapture(e.pointerId)});c.addEventListener('pointermove',e=>{if(!drag)return;this.yaw-=(e.clientX-drag[0])*.008;this.pitch=Math.max(-1.5,Math.min(1.5,this.pitch+(e.clientY-drag[1])*.008));drag=[e.clientX,e.clientY];this.render()});c.addEventListener('pointerup',()=>drag=null);c.addEventListener('wheel',e=>{e.preventDefault();this.radius=Math.max(.2,Math.min(30,this.radius*Math.exp(e.deltaY*.001)));this.render()},{passive:false});new ResizeObserver(()=>this.render()).observe(el);this.render();
 }
 setCameras(cs){this.camGroup.clear();for(let i=0;i<cs.length;i++){const c=cs[i],origin=new THREE.Vector3(...c.center),R=c.R;const dir=new THREE.Vector3(R[6],R[7],R[8]);this.camGroup.add(new THREE.ArrowHelper(dir,origin,.3,i?0xda8b4f:0x337bb4,.06,.04));const box=new THREE.Mesh(new THREE.BoxGeometry(.08,.06,.05),new THREE.MeshBasicMaterial({color:i?0xda8b4f:0x337bb4}));box.position.copy(origin);this.camGroup.add(box);}this.render()}
 setPoints(p,colors){this.surface.geometry.dispose();this.surface.geometry=new THREE.BufferGeometry();this.geometry.dispose();this.geometry=new THREE.BufferGeometry();this.geometry.setAttribute('position',new THREE.BufferAttribute(p,3));this.geometry.setAttribute('color',new THREE.BufferAttribute(colors,3,true));this.cloud.geometry=this.geometry;if(p.length){this.geometry.computeBoundingBox();const b=this.geometry.boundingBox;b.getCenter(this.target);const fit=Math.max(1.3,b.getSize(new THREE.Vector3()).length()*1.5);if(!this.fitted||fit>this.fitted*1.15){this.radius=fit;this.fitted=fit;}}else this.fitted=false;this.render()}
 setFaces(indices){this.surface.geometry.dispose();const g=new THREE.BufferGeometry();g.setAttribute('position',this.geometry.getAttribute('position'));g.setAttribute('color',this.geometry.getAttribute('color'));g.setIndex(new THREE.BufferAttribute(indices,1));this.surface.geometry=g;this.render();}
 showSurface(visible){this.surface.visible=visible;this.render();}
 selectPoints(indices){this.geometry.setIndex(indices?new THREE.BufferAttribute(indices,1):null);this.render();}
 showPoints(visible){this.cloud.visible=visible;this.render();}
 view(v){if(v==='front'){this.yaw=0;this.pitch=0;}if(v==='top'){this.pitch=1.45;this.yaw=0;}if(v==='oblique'){this.pitch=.22;this.yaw=.55;}this.render()}
 render(){const w=this.el.clientWidth,h=this.el.clientHeight;if(!w||!h)return;this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.camera.position.set(this.target.x+this.radius*Math.sin(this.yaw)*Math.cos(this.pitch),this.target.y+this.radius*Math.sin(this.pitch),this.target.z+this.radius*Math.cos(this.yaw)*Math.cos(this.pitch));this.camera.lookAt(this.target);this.renderer.render(this.scene,this.camera)}
}
